interface KalravConfig {
    /** Your Kalrav API key */
    apiKey?: string;
    /** Your agent/bot ID */
    agentId?: string;
    /** Primary color for the widget (default: #4F46E5) */
    primaryColor?: string;
    /** Agent UI type. Omit it for the normal query view; set "ecommerce", "crm", etc. for a specialized view. */
    agentType?: string;
    /** Direct agent UI data used to render type-specific sections */
    agentUiData?: Record<string, any>;
    /** Direct widget settings/config object */
    agentUiSettings?: Record<string, any>;
    /** Endpoint used to fetch widget settings. Use :agentId as a placeholder. */
    agentUiSettingsUrl?: string;
    /** Endpoint used for chat queries */
    queryUrl?: string;
    /** Base URL used for built-in chat/query, upload, and conversation history endpoints */
    chatApiBaseUrl?: string;
    /** Base URL used for built-in settings, ecommerce, pages, leads, and feedback endpoints */
    centralSystemBaseUrl?: string;
    /** Extra headers for custom query endpoint */
    queryHeaders?: Record<string, string>;
    /** Fully custom function for fetching widget settings */
    fetchAgentUiSettings?: (context: {
        agentId?: string;
        apiKey?: string;
    }) => Promise<any>;
    /** Fully custom function for sending chat queries */
    queryFetcher?: (context: any) => Promise<any>;
    /** Maps widget query context into your API payload */
    queryRequestMapper?: (context: any) => any;
    /** Maps your API response into widget response format */
    queryResponseMapper?: (response: any) => any;
    /** Logged-in frontend user ID to send as GA4 kalrav_user_id */
    analyticsUserId?: string;
    /** Auto-load widget on initialization (default: true) */
    autoLoad?: boolean;
    /** Open the chat window automatically after the launcher renders */
    autoOpenWidget?: boolean;
    /** Enable automatic chat-history email sending. Requires emailChatAutoSendTo. */
    emailChatAutoSendEnabled?: boolean;
    /** Recipient email address for automatic chat-history emails. */
    emailChatAutoSendTo?: string;
    /** Automatically email the current chat when the widget is closed. */
    emailChatAutoSendOnClose?: boolean;
    /** Automatically email the current chat before starting a new session. */
    emailChatAutoSendOnNewSession?: boolean;
}
interface KalravWidget {
    /** Load the widget script */
    load(): Promise<void>;
    /** Unload the widget from the page */
    unload(): void;
    /** Open the chat widget */
    open(): void;
    /** Close the chat widget */
    close(): void;
    /** Check if the widget is loaded */
    isLoaded(): boolean;
    /** Call any widget method */
    call(method: string, ...args: any[]): void;
}

export type { KalravConfig as K, KalravWidget as a };
